-- 43_thai_address.sql
--
-- The Thai Post address book, so someone can type a postal code and the system
-- fills in the tambon, district and province instead of them typing it by hand.
-- Source: the owner's Thaipost workbook (Tambon database), 7436 tambons,
-- 928 districts, 77 provinces, 965 distinct postal codes.
--
-- Three tables, not one. The sheet repeats the district and province on every
-- tambon row; keeping it that way would store the same province name 7,436
-- times and let it be spelled two ways. The ids nest exactly
-- (province 2 digits -> district 4 -> tambon 6), which was checked against the
-- data, so the split is lossless.
--
--   "ThaiProvince"  77 rows   name + the four regional groupings the sheet carries
--   "ThaiDistrict"  928 rows  full and short name, Thai and English
--   "ThaiTambon"    7436 rows name, the main postal code, and the rare cases
--                             where one tambon has several
--
-- postCodes holds the sheet's PostCodeAll exactly as given ("10220/10230"), and
-- postCodeRemark the Thai sentence explaining the exception. 97 tambons have
-- more than one code; nothing tries to resolve them automatically, because the
-- remark is the only thing that says which applies.
--
-- Reference data: every row carries ON CONFLICT DO UPDATE, so re-running this
-- after Thai Post revises the list refreshes the names without touching
-- anything else. Additive and idempotent.

CREATE TABLE IF NOT EXISTS "ThaiProvince" (
  "id"             VARCHAR(2) PRIMARY KEY,
  "nameTh"         TEXT NOT NULL,
  "nameEn"         TEXT NOT NULL,
  "regionOfficial" TEXT,
  "region4"        TEXT,
  "regionTourism"  TEXT,
  "metroGroup"     TEXT
);

CREATE TABLE IF NOT EXISTS "ThaiDistrict" (
  "id"          VARCHAR(4) PRIMARY KEY,
  "provinceId"  VARCHAR(2) NOT NULL REFERENCES "ThaiProvince"("id"),
  "nameTh"      TEXT NOT NULL,
  "nameEn"      TEXT NOT NULL,
  "nameThShort" TEXT,
  "nameEnShort" TEXT
);

CREATE TABLE IF NOT EXISTS "ThaiTambon" (
  "id"             VARCHAR(6) PRIMARY KEY,
  "districtId"     VARCHAR(4) NOT NULL REFERENCES "ThaiDistrict"("id"),
  "nameTh"         TEXT NOT NULL,
  "nameEn"         TEXT NOT NULL,
  "nameThShort"    TEXT,
  "nameEnShort"    TEXT,
  -- The code to use. "postCodes" is every code this tambon may use, exactly as
  -- the sheet gives it, and "postCodeRemark" says in Thai when the other applies.
  "postCode"       VARCHAR(5) NOT NULL,
  "postCodes"      TEXT,
  "postCodeRemark" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_thai_district_province" ON "ThaiDistrict" ("provinceId");
CREATE INDEX IF NOT EXISTS "idx_thai_tambon_district"   ON "ThaiTambon" ("districtId");
CREATE INDEX IF NOT EXISTS "idx_thai_tambon_postcode"   ON "ThaiTambon" ("postCode");

